INSERT INTO products_survey_question
  (`id`, `question_id`, `question_text`, `scoring_criteria`, `weight`, `is_active`, `criterion_code`, `criterion_name_th`, `standard_reference`, `display_order`) VALUES
  ('61a09613-762d-40d8-af8c-23432f16d74e', 'c14-q1', 'ธุรกิจของเรามีการเขียนหรือประกาศเป้าหมายระยะยาวในการลดผลกระทบต่อโลกร้อนของธุรกิจเราแล้วหรือไม่', 'คะแนน 1-3: ไม่มีเป้าหมาย | 4-6: มีเป้าหมายแต่ไม่ชัดเจน | 7-8: มีเป้าหมายชัดเจน | 9-10: มีเป้าหมายที่ระบุปีและครอบคลุมทั้งธุรกิจ', '1.50', 1, 'C14', 'การตั้งเป้า net-zero และขอบเขต', 'SBTi', 1),
  ('3b681f61-d11d-44ce-a5cb-080de618e09c', 'c14-q2', 'เป้าหมายเรื่องโลกร้อนของเราครอบคลุมทั้งธุรกิจ ทุกสินค้าและบริการ ไม่ใช่แค่บางส่วนหรือบางโปรเจกต์ ใช่หรือไม่', 'คะแนน 1-3: ครอบคลุมแค่บางส่วน | 4-6: ครอบคลุมส่วนใหญ่ | 7-10: ครอบคลุมทั้งองค์กร', '1.30', 1, 'C14', 'การตั้งเป้า net-zero และขอบเขต', 'SBTi', 2),
  ('edc6dd69-08e5-4f26-8ccd-ce71b622acf3', 'c14-q3', 'ในเป้าหมายเรื่องโลกร้อนของเรา มีการกำหนดปีเป้าหมายชัดเจนไหมว่าภายในปีใด เช่น 2040 2045 หรือ 2050 เราอยากให้ธุรกิจเรากระทบต่อโลกร้อนให้น้อยที่สุด', 'คะแนน 1-3: ไม่มีปีเป้าหมาย | 4-6: มีแต่ยังไม่แน่ชัด | 7-8: มีปีเป้าหมายชัดเจน | 9-10: มีปีเป้าหมาย ≤ 2050', '1.20', 1, 'C14', 'การตั้งเป้า net-zero และขอบเขต', 'SBTi', 3),
  ('01d5c84a-d8f9-4e5d-8d68-070e64dd7069', 'c1-q1', 'เราเคยนั่งลิสต์อย่างจริงจังไหมว่าธุรกิจของเรามีแหล่งการใช้พลังงานและการปล่อยก๊าซเรือนกระจกอะไรบ้าง เช่น การใช้แก๊ส ไฟฟ้า การขนส่ง บรรจุภัณฑ์ และวัตถุดิบ', 'คะแนน 1-3: ยังไม่เริ่ม | 4-6: ลิสต์บางส่วน | 7-8: ลิสต์ครอบคลุมหลักๆ | 9-10: ลิสต์ครบทุกกิจกรรมสำคัญ', '1.40', 1, 'C1-C3,C10', 'การจัดทำ GHG inventory', 'SBTi', 4),
  ('480e8b25-3e13-45b6-bbc5-07759dba6ac9', 'c1-q2', 'สำหรับแหล่งการปล่อยหลัก เช่น การใช้แก๊ส ไฟฟ้า และรถขนส่ง เรามีตัวเลขการใช้งานคร่าวๆ เก็บไว้บ้างหรือไม่ เช่น หน่วยไฟฟ้าต่อเดือน จำนวนถังแก๊ส หรือจำนวนเที่ยวส่งของ', 'คะแนน 1-3: ไม่มีตัวเลข | 4-6: มีบางส่วน | 7-8: มีข้อมูลหลักๆ | 9-10: มีข้อมูลครบถ้วนและเก็บอย่างต่อเนื่อง', '1.30', 1, 'C1-C3,C10', 'การจัดทำ GHG inventory', 'SBTi', 5),
  ('c11c6562-40ed-4e55-9685-97bbe6c2ecb9', 'c1-q3', 'เวลาเราคิดเรื่องมลพิษและการปล่อยก๊าซเรือนกระจกของธุรกิจ เรารวมส่วนที่อยู่นอกกิจการ เช่น การปลูกวัตถุดิบ การผลิตขวดและกล่อง และการขนส่งจากซัพพลายเออร์เข้ามาคิดด้วยหรือไม่', 'คะแนน 1-3: ยังไม่เคยคิด | 4-6: เคยคิดแต่ยังไม่เก็บข้อมูล | 7-8: กำลังเริ่มเก็บข้อมูล | 9-10: เก็บข้อมูล Scope 3 อย่างเป็นระบบ', '1.50', 1, 'C1-C3,C10', 'การจัดทำ GHG inventory', 'SBTi', 6),
  ('4445815f-0ec7-4bee-b830-324c942b9844', 'c5-q1', 'โดยรวมแล้วเราคิดว่าเราได้คิดถึงหรือนับการปล่อยจากกิจกรรมหลักๆ ของธุรกิจเกือบทั้งหมดแล้วใช่หรือไม่ ไม่ได้เลือกนับแค่ส่วนที่ง่ายหรือดูดี', 'คะแนน 1-3: ละเว้นหลายอย่าง | 4-6: ละเว้นพอสมควร | 7-8: ละเว้นเล็กน้อย | 9-10: ละเว้น < 5% ของการปล่อยทั้งหมด', '1.20', 1, 'C5', 'การละเว้นไม่เกิน 5%', 'SBTi', 7),
  ('6913e6ca-4a01-4f57-af8d-bdcf255ea0e7', 'c5-q2', 'สิ่งที่เรายังไม่ได้คิดหรือนับการปล่อย เป็นแค่ส่วนเล็กน้อยมากเมื่อเทียบกับภาพรวมของธุรกิจ เช่น ของใช้สำนักงานเล็กๆ น้อยๆ ใช่หรือไม่', 'คะแนน 1-3: บอกไม่ได้ | 4-6: บอกได้บางส่วน | 7-8: บอกได้ชัดเจน | 9-10: มีเอกสารรองรับและตรวจสอบได้', '1.00', 1, 'C5', 'การละเว้นไม่เกิน 5%', 'SBTi', 8),
  ('a0d5269c-41b4-4faf-9940-23b7ad84595f', 'c4-q1', 'มองภาพรวมทั้งธุรกิจแล้ว เรารู้สึกไหมว่ามลพิษและการปล่อยก๊าซเรือนกระจกส่วนใหญ่ของเรามาจากนอกกิจการ เช่น ฟาร์มวัตถุดิบ โรงงานทำบรรจุภัณฑ์ และการขนส่ง มากกว่ามาจากไฟฟ้าหรือแก๊สในร้านหรือโรงงานของเราเอง', 'คะแนน 1-3: ไม่แน่ใจ | 4-6: น่าจะใช่ | 7-8: แน่ใจว่าส่วนใหญ่มาจากภายนอก | 9-10: มีตัวเลขยืนยันว่า Scope 3 ≥ 40%', '1.40', 1, 'C4', 'ความสำคัญของ Scope 3', 'SBTi', 9),
  ('dd488b8a-cc03-4577-8651-c16df578f896', 'c4-q2', 'เวลาเราเขียนหรือพูดถึงเป้าหมายลดผลกระทบต่อโลกร้อนของธุรกิจ เราได้พูดถึงการทำงานร่วมกับซัพพลายเออร์ ผู้ผลิตวัตถุดิบ และผู้ให้บริการขนส่งด้วยหรือไม่', 'คะแนน 1-3: ยังไม่ระบุ | 4-6: กล่าวถึงบางส่วน | 7-8: ระบุชัดเจน | 9-10: มีเป้าหมายและแผนการลด Scope 3 ที่เป็นรูปธรรม', '1.50', 1, 'C4', 'ความสำคัญของ Scope 3', 'SBTi', 10),
  ('067094cb-4081-4ffd-bfcd-783afa71e761', 'c4-q3', 'เวลาเราเล่าให้คนอื่นฟังว่าเรามีแผนลดมลพิษของธุรกิจ เราพูดถึงทั้งสิ่งที่เกิดในร้านหรือโรงงานของเรา และสิ่งที่เกิดขึ้นในห่วงโซ่อุปทาน เช่น การปลูกวัตถุดิบและการขนส่ง หรือไม่', 'คะแนน 1-3: ไม่กล่าวถึง | 4-6: กล่าวถึงบางเรื่อง | 7-8: กล่าวถึงชัดเจน | 9-10: มีแผนงานและตัวชี้วัดสำหรับซัพพลายเชน', '1.30', 1, 'C4', 'ความสำคัญของ Scope 3', 'SBTi', 11),
  ('e32a050a-2fb5-47d0-bfd0-73b030e57abd', 'c6-q1', 'ในแผนลดผลกระทบต่อโลกร้อนของเรา เราได้ใส่มาตรการสำหรับหลายส่วนสำคัญของมลพิษทางอ้อม เช่น วัตถุดิบที่ซื้อมา บรรจุภัณฑ์ การขนส่ง และการจัดการขยะ ไม่ได้โฟกัสแค่เรื่องเดียวใช่หรือไม่', 'คะแนน 1-3: ครอบคลุมน้อยมาก | 4-6: ครอบคลุมบางส่วน | 7-8: ครอบคลุมส่วนใหญ่ ≥ 67% | 9-10: ครอบคลุม ≥ 90%', '1.40', 1, 'C6-C7', 'การครอบคลุม Scope 3', 'SBTi', 12),
  ('bf72661c-b207-4fb1-b2b4-ac76c121900f', 'c6-q2', 'ในระยะยาว เราตั้งใจไหมว่าแผนของเราจะค่อยๆ ครอบคลุมแทบทุกส่วนสำคัญที่ทำให้ธุรกิจเรามีมลพิษและกระทบต่อโลกร้อน ทั้งในร้านและในห่วงโซ่อุปทาน', 'คะแนน 1-3: ยังไม่มีแผน | 4-6: ตั้งใจแต่ยังไม่ชัดเจน | 7-8: มีแผนขยายเป็นขั้นเป็นตอน | 9-10: มีแผนครอบคลุม 90% ภายในปีเป้าหมาย', '1.30', 1, 'C6-C7', 'การครอบคลุม Scope 3', 'SBTi', 13),
  ('1921da34-a530-44d1-a57b-cfda84b2c9cb', 'c16-q1', 'เรามีปีเริ่มต้นอ้างอิงชัดเจนสำหรับใช้เปรียบเทียบการปล่อยก๊าซเรือนกระจกของธุรกิจ เช่น เลือกปีเริ่มต้นตั้งแต่ปี 2015 ขึ้นไป เช่น ปี 2020 หรือปี 2023 หรือไม่', 'คะแนน 1-3: ไม่มีปีฐาน | 4-6: มีแต่ไม่ชัดเจน | 7-8: มีปีฐานชัดเจน | 9-10: มีปีฐาน ≥ 2015 พร้อมข้อมูล', '1.20', 1, 'C16-C17', 'กรอบเวลาของเป้าหมาย', 'SBTi', 14),
  ('ae83ec8d-c5de-4fb9-851b-36da34e00aed', 'c16-q2', 'เรามีเป้าหมายระยะกลาง ภายในประมาณห้าถึงสิบปีข้างหน้า เช่น ภายในปี 2030 อยากให้การปล่อยจากธุรกิจเราลดลงอย่างชัดเจนหรือไม่', 'คะแนน 1-3: ไม่มี | 4-6: มีแต่ไม่ชัด | 7-8: มีเป้าหมายชัดเจน | 9-10: มีเป้าหมายระยะกลางที่วัดผลได้', '1.30', 1, 'C16-C17', 'กรอบเวลาของเป้าหมาย', 'SBTi', 15),
  ('f5f8081f-339b-4320-94c0-d6705c0f14c8', 'c16-q3', 'เรามีเป้าหมายระยะยาวว่าภายในปีใด เช่น 2040 2045 หรือ 2050 เราอยากให้ธุรกิจเรามีการปล่อยก๊าซเรือนกระจกเหลือน้อยที่สุดเท่าที่ทำได้หรือไม่', 'คะแนน 1-3: ไม่มี | 4-6: มีแต่เกิน 2050 | 7-8: มีภายใน 2050 | 9-10: มีภายใน 2045 หรือก่อนหน้า', '1.40', 1, 'C16-C17', 'กรอบเวลาของเป้าหมาย', 'SBTi', 16),
  ('a3515af2-422f-421a-a19e-7bf608eafeae', 'c19-q1', 'เมื่อมองอนาคตระยะยาว เราตั้งใจไหมว่าธุรกิจของเราจะลดการปล่อยก๊าซเรือนกระจกลงในระดับมาก เช่น มากกว่าครึ่งหนึ่งของระดับปัจจุบัน', 'คะแนน 1-3: ลดนิดเดียว | 4-6: ลดพอสมควร | 7-8: ลดมากกว่าครึ่ง | 9-10: ลดเกือบทั้งหมด ≥ 90%', '1.50', 1, 'C19-C25', 'ความทะเยอทะยานสอดคล้อง 1.5°C', 'SBTi', 17),
  ('a4ea075f-ee01-4025-bb2a-680b059b6787', 'c19-q2', 'เรามีแผนคร่าวๆ ไหมว่าจะทบทวนและหาวิธีลดการปล่อยเพิ่มเติมเป็นระยะ เช่น ทุกสองถึงสามปี แทนที่จะทำเพียงครั้งเดียวแล้วหยุด', 'คะแนน 1-3: ไม่มีแผนต่อเนื่อง | 4-6: ตั้งใจแต่ยังไม่เป็นรูปธรรม | 7-8: มีแผนทบทวนเป็นระยะ | 9-10: มีแผนลดอย่างต่อเนื่องทุกรอบ', '1.30', 1, 'C19-C25', 'ความทะเยอทะยานสอดคล้อง 1.5°C', 'SBTi', 18),
  ('c32cd4bd-432d-498e-ad24-c2dca70f8be2', 'c19-q3', 'เวลาเราตัดสินใจลงทุนหรือเปลี่ยนวิธีทำงานในธุรกิจ เราเคยถามตัวเองไหมว่าสิ่งนั้นช่วยลดการปล่อยก๊าซเรือนกระจกได้มากพอและคุ้มค่าหรือเป็นเพียงการเปลี่ยนเล็กน้อย', 'คะแนน 1-3: ไม่เคยคิด | 4-6: เคยคิดบ้าง | 7-8: คิดเป็นประจำ | 9-10: มีเกณฑ์ประเมินผลกระทบก่อนตัดสินใจลงทุน', '1.20', 1, 'C19-C25', 'ความทะเยอทะยานสอดคล้อง 1.5°C', 'SBTi', 19),
  ('0958a2e5-798b-4325-9b04-db3c9b4b8357', 'c12-q1', 'ในตอนนี้เรามุ่งเน้นการลดการใช้พลังงาน เชื้อเพลิง และวัตถุดิบของธุรกิจตัวเองก่อนที่จะไปซื้อคาร์บอนเครดิตใช่หรือไม่', 'คะแนน 1-3: พึ่งเครดิตเป็นหลัก | 4-6: พอๆ กัน | 7-8: โฟกัสการลดก่อน | 9-10: ลดสูงสุดก่อน ใช้เครดิตเฉพาะส่วนที่เหลือ', '1.40', 1, 'C12', 'ใช้ offset เฉพาะส่วนที่เหลือ', 'SBTi', 20),
  ('252e722a-402a-40a0-8aa9-702ed484ca60', 'c12-q2', 'ถ้าเราสนับสนุนการปลูกป่าหรือซื้อคาร์บอนเครดิต เราแยกชัดหรือไม่ว่านี่คือการช่วยโลกเพิ่มเติม ไม่ใช่เหตุผลหลักที่ทำให้เราบอกว่าได้ลดการปล่อยของธุรกิจตามเป้าแล้ว', 'คะแนน 1-3: ไม่แยก นับรวมกัน | 4-6: ค่อนข้างแยก | 7-8: แยกชัดเจน | 9-10: บัญชีแยกชัดเจน ไม่นับเครดิตเป็น progress', '1.30', 1, 'C12', 'ใช้ offset เฉพาะส่วนที่เหลือ', 'SBTi', 21),
  ('62107386-3f2e-4064-a5d0-a0f268a7ae29', 'c12-q3', 'เราเข้าใจหรือไม่ว่าตามแนวคิดสากล คาร์บอนเครดิตควรใช้กับส่วนการปล่อยเล็กน้อยที่เหลืออยู่หลังจากเราพยายามลดการปล่อยของตัวเองอย่างเต็มที่แล้วเท่านั้น', 'คะแนน 1-3: ไม่เข้าใจ | 4-6: เข้าใจบางส่วน | 7-8: เข้าใจดี | 9-10: เข้าใจและปฏิบัติตามหลักการนี้อย่างเคร่งครัด', '1.20', 1, 'C12', 'ใช้ offset เฉพาะส่วนที่เหลือ', 'SBTi', 22),
  ('b7e562d2-db7b-4a6f-a6d9-e541301eea5e', 'iso-equity-q1', 'เวลาเราปรับวิธีทำงานเพื่อลดผลกระทบต่อโลกร้อน เราคิดถึงผลดีผลเสียต่อเกษตรกร ซัพพลายเออร์ พนักงาน และชุมชนรอบธุรกิจของเราบ้างหรือไม่', 'คะแนน 1-3: ไม่คิด | 4-6: คิดบ้าง | 7-8: คิดเป็นประจำ | 9-10: มีกระบวนการประเมินผลกระทบต่อผู้มีส่วนได้ส่วนเสีย', '1.30', 1, 'ISO-equity', 'ผลกระทบกว้างและความเป็นธรรม', 'ISO_IWA_42', 23),
  ('9fd79568-a464-47c8-9502-75fbcc1074b4', 'iso-equity-q2', 'เวลาเราขอให้คู่ค้าช่วยลดผลกระทบต่อสิ่งแวดล้อม เราพยายามช่วยคิดหรือช่วยรับต้นทุนบางส่วน แทนที่จะให้คู่ค้าต้องรับภาระเพียงฝ่ายเดียวหรือไม่', 'คะแนน 1-3: ไม่เคยคุย | 4-6: คุยบ้าง | 7-8: คุยและร่วมมือกัน | 9-10: มีโครงการสนับสนุนคู่ค้าในการลดผลกระทบ', '1.20', 1, 'ISO-equity', 'ผลกระทบกว้างและความเป็นธรรม', 'ISO_IWA_42', 24),
  ('2cc62427-929b-4cdd-8f9d-7efdf3fec1d4', 'iso-equity-q3', 'ธุรกิจของเรามีกิจกรรมง่ายๆ ที่ช่วยดูแลธรรมชาติรอบตัวบ้างไหม เช่น ลดการเผา ไม่ปล่อยน้ำเสียลงแหล่งน้ำ และลดการใช้สารเคมีที่เป็นอันตราย', 'คะแนน 1-3: ไม่ทำ | 4-6: ทำบางอย่าง | 7-8: ทำหลายอย่าง | 9-10: มีนโยบายและแผนดูแลสิ่งแวดล้อมครบวงจร', '1.10', 1, 'ISO-equity', 'ผลกระทบกว้างและความเป็นธรรม', 'ISO_IWA_42', 25),
  ('73b3e310-def4-4a5e-b31c-845077e5c9a1', 'iso-transparency-q1', 'ในแต่ละปี เราจดบันทึกหรือสรุปไว้ไหมว่าธุรกิจของเราได้ทำอะไรไปบ้างเพื่อให้กระทบต่อโลกร้อนน้อยลง เช่น โครงการที่ทำและผลที่เกิดขึ้นคร่าวๆ', 'คะแนน 1-3: ไม่บันทึก | 4-6: บันทึกบางส่วน | 7-8: บันทึกและทบทวนเป็นประจำ | 9-10: มีระบบติดตามและรายงานอย่างเป็นทางการ', '1.30', 1, 'ISO-transparency', 'ความโปร่งใสและการรายงาน', 'ISO_IWA_42', 26),
  ('0268de5d-9452-45ac-94b3-b1731f3ebc2f', 'iso-transparency-q2', 'เราเคยนำข้อมูลหรือเรื่องราวเกี่ยวกับการลดผลกระทบต่อโลกร้อนไปเล่าให้ลูกค้า ชุมชน หรือคนทั่วไปเห็นบ้างไหม เช่น ผ่านโซเชียลมีเดีย เว็บไซต์ หรือเอกสารสั้นๆ', 'คะแนน 1-3: ไม่แชร์ | 4-6: แชร์บางครั้ง | 7-8: แชร์เป็นประจำ | 9-10: มีรายงานสาธารณะและอัพเดทสม่ำเสมอ', '1.20', 1, 'ISO-transparency', 'ความโปร่งใสและการรายงาน', 'ISO_IWA_42', 27),
  ('5f472e8e-4154-4afa-b929-9156612feaea', 'iso-transparency-q3', 'เคยมีคนภายนอก เช่น ที่ปรึกษา มหาวิทยาลัย หรือองค์กรอื่น มาช่วยดูหรือซักถามเกี่ยวกับข้อมูลและคำอธิบายเรื่องการลดการปล่อยของเราบ้างหรือไม่', 'คะแนน 1-3: ไม่เคยมี | 4-6: เคยปรึกษา | 7-8: มีที่ปรึกษาดูแลเป็นระยะ | 9-10: มีการตรวจสอบโดยบุคคลภายนอกอย่างเป็นทางการ', '1.40', 1, 'ISO-transparency', 'ความโปร่งใสและการรายงาน', 'ISO_IWA_42', 28);
